Vector2
WorldToScreen(Vector2 point, Camera camera)
{
    float sine = SineDegrees(camera.rotation);
    float cosine = CosineDegrees(camera.rotation);
    float x = (point.x - camera.target.x) * camera.zoom;
    float y = (point.y - camera.target.y) * camera.zoom;
    return (Vector2){.x = (camera.offset.x + (x * cosine)) - (y * sine), .y = (camera.offset.y + (x * sine)) + (y * cosine)};
}

Rectangle
RectangleIntersection(Rectangle a, Rectangle b)
{
    Rectangle result = {0};
    float right = a.x + a.width;
    float bottom = a.y + a.height;
    float other_right = b.x + b.width;
    float other_bottom = b.y + b.height;
    result.x = a.x;
    if (b.x > a.x) {
        result.x = b.x;
    }
    result.y = a.y;
    if (b.y > a.y) {
        result.y = b.y;
    }
    if (other_right < right) {
        right = other_right;
    }
    if (other_bottom < bottom) {
        bottom = other_bottom;
    }
    result.width = right - result.x;
    result.height = bottom - result.y;
    if (result.width < ((float)0.0)) {
        result.width = (float)0.0;
    }
    if (result.height < ((float)0.0)) {
        result.height = (float)0.0;
    }
    return result;
}

Rectangle
geometry_RotatedRectangleBounds(Rectangle bounds, Vector2 origin, float rotation)
{
    Camera camera = {.offset = origin, .target = origin, .rotation = rotation, .zoom = (float)1.0};
    Vector2 points[4] = {{.x = bounds.x, .y = bounds.y}, {.x = bounds.x + bounds.width, .y = bounds.y}, {.x = bounds.x + bounds.width, .y = bounds.y + bounds.height}, {.x = bounds.x, .y = bounds.y + bounds.height}};
    Vector2 first = WorldToScreen((points)[0], camera);
    float left = first.x;
    float right = first.x;
    float top = first.y;
    float bottom = first.y;
    for (int64_t it_index = 0LL; it_index < 4; it_index++) {
        Vector2 point = (points)[it_index];
        Vector2 at = WorldToScreen(point, camera);
        if (at.x < left) {
            left = at.x;
        }
        if (at.x > right) {
            right = at.x;
        }
        if (at.y < top) {
            top = at.y;
        }
        if (at.y > bottom) {
            bottom = at.y;
        }
    }
    return (Rectangle){.x = left, .y = top, .width = right - left, .height = bottom - top};
}
